import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { 
  Home, 
  CheckSquare, 
  Target, 
  Calendar, 
  TrendingUp, 
  BookOpen,
  LogOut
} from 'lucide-react';

const Sidebar = () => {
  const location = useLocation();
  const { logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const navItems = [
    { to: '/dashboard', icon: Home, label: 'Dashboard', color: 'text-blue-600' },
    { to: '/tasks', icon: CheckSquare, label: 'Tasks', color: 'text-green-600' },
    { to: '/goals', icon: Target, label: 'Goals', color: 'text-purple-600' },
    { to: '/calendar', icon: Calendar, label: 'Calendar', color: 'text-orange-600' },
    { to: '/progress', icon: TrendingUp, label: 'Progress', color: 'text-pink-600' },
    { to: '/diary', icon: BookOpen, label: 'Diary', color: 'text-indigo-600' }
  ];

  return (
    <div className="fixed left-0 top-16 h-full w-64 bg-white border-r border-gray-200 shadow-sm z-40 flex flex-col">
      <div className="p-6 flex-1">
        <nav className="space-y-2">
          {navItems.map((item) => {
            const isActive = location.pathname === item.to;
            return (
              <Link
                key={item.to}
                to={item.to}
                className={`group flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                  isActive 
                    ? 'bg-blue-50 text-blue-600 border border-blue-100' 
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-50'
                }`}
              >
                <item.icon 
                  size={20} 
                  className={`${isActive ? 'text-blue-600' : `group-hover:${item.color}`} transition-colors`} 
                />
                <span className="font-medium">{item.label}</span>
              </Link>
            );
          })}
        </nav>
      </div>

      <div className="p-6 border-t border-gray-200">
        <button
          onClick={handleLogout}
          className="flex items-center space-x-3 w-full px-4 py-3 text-red-600 hover:bg-red-50 rounded-xl transition-all duration-200"
        >
          <LogOut size={20} />
          <span className="font-medium">Sign Out</span>
        </button>
      </div>
    </div>
  );
};

export default Sidebar;
